// Report whether the first tornado of the map is out on the pitch
IsActiveTornade <- function ()
{
	if (CMND_BTL_IS_ACTIVE_TORNADE(hTornade[0]))
	{
		return true;
	}

	return false;
};

// Avoid moving a tornado that is already active
if (!CMND_BTL_IS_ACTIVE_TORNADE(hTornade[1]))
{
	CMND_BTL_ACTIVE_TORNADE(hTornade[1], 0.0, 120.0);
}
